(function() {
    'use strict';

    class HelixCLVAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Customer Lifetime Value Lab';
            this.version = '1.1.0';

            this.EVENT_CARDS = [
                {
                    en: `Round 1 — Competitive Threat: The largest competitor has launched a 40% price cut on their Starter tier. Your SMB segment faces immediate churn risk. Will you match the price or defend with value?`,
                    es: `Ronda 1 — Amenaza Competitiva: El mayor competidor ha lanzado un recorte de precio del 40% en su nivel Starter. Su segmento SMB enfrenta riesgo inmediato de cancelacion. ¿Iguala el precio o defiende con valor?`
                },
                {
                    en: `Round 2 — Market Validation: A top-tier law firm association has published a case study citing Helix as a best-in-class solution. Inbound pipeline from law firms is surging. Your ICP hypothesis is being tested.`,
                    es: `Ronda 2 — Validacion de Mercado: Una asociacion de firmas de abogados de primer nivel ha publicado un caso de estudio citando a Helix. El pipeline de firmas legales esta creciendo. Su hipotesis de ICP esta siendo probada.`
                },
                {
                    en: `Round 3 — Macro Headwind: A global recession indicator shows professional services firms cutting software budgets by 15%. CAC is rising and churn is increasing. Burn management is now critical.`,
                    es: `Ronda 3 — Viento en Contra Macro: Un indicador de recesion global muestra que las firmas de servicios profesionales recortan presupuestos de software un 15%. El CAC sube y la cancelacion aumenta. La gestion de quema de caja es critica.`
                },
                {
                    en: `Round 4 — Competitive Escalation: A VC-backed competitor has raised $30M and tripled their enterprise sales team. Sales cycles are lengthening and competitive situations are increasing.`,
                    es: `Ronda 4 — Escalada Competitiva: Un competidor respaldado por capital de riesgo ha recaudado $30M y triplicado su equipo de ventas enterprise. Los ciclos de ventas se alargan y aumentan las situaciones competitivas.`
                },
                {
                    en: `Round 5 — Upsell Opportunity: Helix integration with a major legal practice management platform has won an industry award. An enterprise upsell wave is emerging among existing law firm customers.`,
                    es: `Ronda 5 — Oportunidad de Upsell: La integracion de Helix con una plataforma de gestion de practica legal gano un premio de la industria. Surge una ola de upsell entre los clientes de firmas legales existentes.`
                },
                {
                    en: `Round 6 — Series B Due Diligence: The Series B investor is conducting due diligence. They are requesting 3-year cohort data and a clear unit economics narrative. Your decisions this quarter are under a microscope.`,
                    es: `Ronda 6 — Due Diligence Serie B: El inversor de Serie B esta realizando due diligence. Solicitan datos de cohorte de 3 años y una narrativa clara de economia unitaria. Sus decisiones este trimestre estan bajo un microscopio.`
                }
            ];

            this.BASE_SMB_CUSTOMERS = 600;
            this.BASE_ENT_CUSTOMERS = 12;
            this.INITIAL_CASH = 8000000;
            this.BASE_MONTHLY_BURN = 280000;
            // Stable structural bases — effective values each quarter are derived from these
            // (NOT from the previous quarter's already-multiplied value) to prevent runaway compounding.
            this.BASE_BLENDED_CAC = 2100;
            this.BASE_ENT_CAC = 24000;
            this.BASE_SMB_CHURN = 0.038;
            this.BASE_ENT_CHURN = 0.011;

            this.ICP_PARAMS = {
                broad:      { churnMult: 1.0,  cacMult: 1.0,  newLogoMult: 1.0,  upsellMult: 1.0 },
                law:        { churnMult: 0.37, cacMult: 1.2,  newLogoMult: 0.8,  upsellMult: 1.6 },
                accounting: { churnMult: 0.55, cacMult: 0.85, newLogoMult: 0.9,  upsellMult: 1.1 },
                enterprise: { churnMult: 0.29, cacMult: 2.5,  newLogoMult: 0.3,  upsellMult: 1.9 }
            };

            this.CAC_STRATEGY_PARAMS = {
                disciplined: { cacMult: 1.0, newLogoMult: 1.0, burnMult: 1.0 },
                aggressive:  { cacMult: 1.35, newLogoMult: 1.6, burnMult: 1.4 },
                conservative:{ cacMult: 0.75, newLogoMult: 0.6, burnMult: 0.65 }
            };

            this.CS_PARAMS = {
                minimal:  { churnMult: 1.22, upsellMult: 0.6,  burnAdd: 20000 },
                standard: { churnMult: 1.0,  upsellMult: 1.0,  burnAdd: 50000 },
                intensive:{ churnMult: 0.72, upsellMult: 1.55, burnAdd: 95000 }
            };

            this.UPSELL_PARAMS = {
                reactive:  { upsellRate: 0.012 },
                proactive: { upsellRate: 0.028 },
                automated: { upsellRate: 0.020 }
            };

            this.PRICING_PARAMS = {
                maintain:         { nrrBoost: 0,    cashMult: 1.0,   cacMult: 1.0 },
                annual:           { nrrBoost: 0.04, cashMult: 1.18,  cacMult: 0.95 },
                usage:            { nrrBoost: 0.03, cashMult: 1.08,  cacMult: 1.0 },
                enterprise_value: { nrrBoost: 0.06, cashMult: 1.25,  cacMult: 1.1 }
            };

            this.PRODUCT_PARAMS = {
                none:         { churnMult: 1.0,  upsellMult: 1.0,  cost: 0 },
                integrations: { churnMult: 0.82, upsellMult: 1.3,  cost: 80000 },
                ai:           { churnMult: 0.78, upsellMult: 1.1,  cost: 70000 },
                analytics:    { churnMult: 0.90, upsellMult: 1.45, cost: 60000 },
                mobile:       { churnMult: 0.85, upsellMult: 1.05, cost: 50000 }
            };

            this.EVENT_MODIFIERS = [
                { smbChurnBoost: 0.008, entChurnBoost: 0,     cacBoost: 1.0,  mrrMult: 1.0  },
                { smbChurnBoost: -0.005,entChurnBoost: -0.002, cacBoost: 0.9,  mrrMult: 1.08 },
                { smbChurnBoost: 0.010, entChurnBoost: 0.003, cacBoost: 1.18, mrrMult: 0.95 },
                { smbChurnBoost: 0.004, entChurnBoost: 0.005, cacBoost: 1.25, mrrMult: 0.97 },
                { smbChurnBoost: -0.003,entChurnBoost: -0.005, cacBoost: 0.95, mrrMult: 1.0  },
                { smbChurnBoost: 0,     entChurnBoost: 0,     cacBoost: 1.0,  mrrMult: 1.0  }
            ];
        }

        initialize(state) {
            if (this._cardTimer) { clearTimeout(this._cardTimer); this._cardTimer = null; }
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    cash: this.INITIAL_CASH,
                    smbCustomers: this.BASE_SMB_CUSTOMERS,
                    entCustomers: this.BASE_ENT_CUSTOMERS,
                    smbChurnRate: 0.038,
                    entChurnRate: 0.011,
                    smbARPU: 166,
                    entARPU: 3500,
                    smbGrossMargin: 0.72,
                    entGrossMargin: 0.78,
                    blendedCAC: 2100,
                    entCAC: 24000,
                    totalMRR: 0,
                    prevMRR: 0,
                    expansionMRR: 0,
                    churnedMRR: 0,
                    newMRR: 0,
                    nrr: 0.94,
                    ltvCacRatio: 0,
                    cacPaybackMonths: 0,
                    runwayMonths: 18,
                    mrrHistory: [],
                    nrrHistory: [],
                    ltvCacHistory: [],
                    seriesBScore: 0,
                    productInvestments: []
                };
                // Fresh game: reset the per-period domainState snapshot stack.
                this._snapshots = {};
                this._snapshots[1] = JSON.parse(JSON.stringify(state.domainState));
            } else if (this._snapshots && this._snapshots[state.currentPeriod]) {
                // Undo path: framework rolled currentPeriod back and re-called initialize.
                // Restore the domainState captured when the player entered this period.
                state.domainState = JSON.parse(JSON.stringify(this._snapshots[state.currentPeriod]));
                var _sp = this._snapshots;
                Object.keys(_sp).forEach(function(k) { if (+k > state.currentPeriod) delete _sp[k]; });
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    acqBudget: 60000,
                    icpTarget: 'broad',
                    cacStrategy: 'disciplined',
                    csInvestment: 'standard',
                    upsellMotion: 'reactive',
                    pricing: 'maintain',
                    productInvest: 'none'
                };
            }
            this._updateEventCard(state);
            this._computeDisplayMetrics(state);
        }

        validateDecisions(decisions) {
            const acqEl = document.getElementById('acqBudgetInput');
            const icpEl = document.getElementById('icpSelect');
            const cacEl = document.getElementById('cacStrategySelect');
            const csEl = document.getElementById('csInvestmentSelect');
            const upsellEl = document.getElementById('upsellMotionSelect');
            const pricingEl = document.getElementById('pricingSelect');
            const productEl = document.getElementById('productInvestSelect');

            if (acqEl) decisions.acqBudget = parseFloat(acqEl.value) || 0;
            if (icpEl) decisions.icpTarget = icpEl.value;
            if (cacEl) decisions.cacStrategy = cacEl.value;
            if (csEl) decisions.csInvestment = csEl.value;
            if (upsellEl) decisions.upsellMotion = upsellEl.value;
            if (pricingEl) decisions.pricing = pricingEl.value;
            if (productEl) decisions.productInvest = productEl.value;

            if (decisions.acqBudget < 0 || decisions.acqBudget > 200000) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('budget_warning'), 'warning'
                );
                return false;
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            // Snapshot the entering state of THIS period so Undo can restore it.
            this._snapshots = this._snapshots || {};
            this._snapshots[state.currentPeriod || 1] = JSON.parse(JSON.stringify(ds));
            const periodIdx = Math.min((state.currentPeriod || 1) - 1, this.EVENT_MODIFIERS.length - 1);
            const evMod = this.EVENT_MODIFIERS[periodIdx];

            const icp = this.ICP_PARAMS[d.icpTarget] || this.ICP_PARAMS['broad'];
            const cacStr = this.CAC_STRATEGY_PARAMS[d.cacStrategy] || this.CAC_STRATEGY_PARAMS['disciplined'];
            const cs = this.CS_PARAMS[d.csInvestment] || this.CS_PARAMS['standard'];
            const upsell = this.UPSELL_PARAMS[d.upsellMotion] || this.UPSELL_PARAMS['reactive'];
            const pricing = this.PRICING_PARAMS[d.pricing] || this.PRICING_PARAMS['maintain'];
            const prod = this.PRODUCT_PARAMS[d.productInvest] || this.PRODUCT_PARAMS['none'];

            var effectiveSmbChurn = Math.max(0.005, (this.BASE_SMB_CHURN + evMod.smbChurnBoost) * icp.churnMult * cs.churnMult * prod.churnMult);
            var effectiveEntChurn = Math.max(0.003, (this.BASE_ENT_CHURN + evMod.entChurnBoost) * icp.churnMult * cs.churnMult * prod.churnMult * 0.5);

            var periodsPerQuarter = 3;
            var smbChurned = Math.round(ds.smbCustomers * (1 - Math.pow(1 - effectiveSmbChurn, periodsPerQuarter)));
            var entChurned = Math.round(ds.entCustomers * (1 - Math.pow(1 - effectiveEntChurn, periodsPerQuarter)));

            var blendedEffectiveCAC = this.BASE_BLENDED_CAC * icp.cacMult * cacStr.cacMult * evMod.cacBoost;
            var entEffectiveCAC = this.BASE_ENT_CAC * cacStr.cacMult * evMod.cacBoost;

            var budgetPerMonth = d.acqBudget;
            var smbBudget = d.icpTarget === 'enterprise' ? 0 : budgetPerMonth * 0.75;
            var entBudget = d.icpTarget === 'enterprise' ? budgetPerMonth * 1.0 : budgetPerMonth * 0.25;

            var newSMB = blendedEffectiveCAC > 0 ? Math.floor((smbBudget * 3 * icp.newLogoMult * cacStr.newLogoMult) / blendedEffectiveCAC) : 0;
            var newEnt = entEffectiveCAC > 0 ? Math.floor((entBudget * 3 * icp.newLogoMult * cacStr.newLogoMult) / entEffectiveCAC) : 0;
            if (d.icpTarget === 'broad' || d.icpTarget === 'law' || d.icpTarget === 'accounting') {
                newEnt = Math.max(0, newEnt);
            }

            var prevSMB = ds.smbCustomers;
            var prevEnt = ds.entCustomers;
            ds.smbCustomers = Math.max(0, ds.smbCustomers - smbChurned + newSMB);
            ds.entCustomers = Math.max(0, ds.entCustomers - entChurned + newEnt);

            var smbUpsellCount = Math.round(ds.smbCustomers * upsell.upsellRate * icp.upsellMult * cs.upsellMult * prod.upsellMult * periodsPerQuarter);
            var entUpsellRevenue = ds.entCustomers * 0.08 * upsell.upsellRate * icp.upsellMult * cs.upsellMult * prod.upsellMult * periodsPerQuarter * ds.entARPU;

            if (d.pricing === 'enterprise_value') {
                ds.entARPU = Math.min(ds.entARPU * 1.12, 5000);
            }
            var effectiveSmbARPU = d.pricing === 'usage' ? ds.smbARPU * 1.08 : ds.smbARPU;
            var effectiveEntARPU = ds.entARPU;

            var newMRR = (newSMB * effectiveSmbARPU) + (newEnt * effectiveEntARPU);
            var churnedMRR = (smbChurned * effectiveSmbARPU) + (entChurned * effectiveEntARPU);
            var expansionMRR = (smbUpsellCount * (effectiveSmbARPU * 0.5)) + entUpsellRevenue;
            expansionMRR = Math.round(expansionMRR);

            var prevTotalMRR = ds.totalMRR || ((prevSMB * effectiveSmbARPU) + (prevEnt * effectiveEntARPU));
            var currentMRR = (ds.smbCustomers * effectiveSmbARPU) + (ds.entCustomers * effectiveEntARPU) + (expansionMRR * 0.3);
            currentMRR = Math.round(currentMRR * evMod.mrrMult);

            if (d.pricing === 'annual') { currentMRR = Math.round(currentMRR * 1.08); }

            var nrr = prevTotalMRR > 0 ? ((currentMRR - newMRR) / prevTotalMRR) : 0.94;
            nrr = Math.min(nrr + pricing.nrrBoost, 1.60);
            nrr = Math.max(nrr, 0.70);

            var smbLTV = effectiveSmbARPU * ds.smbGrossMargin * (1 / effectiveSmbChurn);
            var entLTV = effectiveEntARPU * ds.entGrossMargin * (1 / effectiveEntChurn);
            var blendedLTV = ((smbLTV * ds.smbCustomers) + (entLTV * ds.entCustomers)) / Math.max(1, ds.smbCustomers + ds.entCustomers);
            var blendedCACForRatio = ((blendedEffectiveCAC * ds.smbCustomers) + (entEffectiveCAC * ds.entCustomers)) / Math.max(1, ds.smbCustomers + ds.entCustomers);
            var ltvCacRatio = blendedCACForRatio > 0 ? blendedLTV / blendedCACForRatio : 0;

            var smbPayback = (effectiveSmbARPU * ds.smbGrossMargin) > 0 ? blendedEffectiveCAC / (effectiveSmbARPU * ds.smbGrossMargin) : 99;
            var entPayback = (effectiveEntARPU * ds.entGrossMargin) > 0 ? entEffectiveCAC / (effectiveEntARPU * ds.entGrossMargin) : 99;
            var blendedPayback = ((smbPayback * ds.smbCustomers) + (entPayback * ds.entCustomers)) / Math.max(1, ds.smbCustomers + ds.entCustomers);

            var quarterlyMRRIncome = currentMRR * 3 * pricing.cashMult;
            var quarterlyBurn = (this.BASE_MONTHLY_BURN + cs.burnAdd) * cacStr.burnMult * 3;
            var quarterlyAcqSpend = d.acqBudget * 3;
            var productCost = prod.cost;
            var netCashChange = quarterlyMRRIncome - quarterlyBurn - quarterlyAcqSpend - productCost;
            ds.cash += netCashChange;
            ds.cash = Math.max(0, ds.cash);

            var monthlyBurnEstimate = (quarterlyBurn + quarterlyAcqSpend + productCost) / 3;
            var monthlyIncome = currentMRR * pricing.cashMult;
            var netMonthlyBurn = Math.max(0, monthlyBurnEstimate - monthlyIncome);
            var runwayMonths = netMonthlyBurn > 0 ? Math.floor(ds.cash / netMonthlyBurn) : 99;
            runwayMonths = Math.min(runwayMonths, 60);

            ds.prevMRR = prevTotalMRR;
            ds.totalMRR = currentMRR;
            ds.newMRR = Math.round(newMRR);
            ds.churnedMRR = Math.round(churnedMRR);
            ds.expansionMRR = expansionMRR;
            ds.nrr = nrr;
            ds.ltvCacRatio = ltvCacRatio;
            ds.cacPaybackMonths = blendedPayback;
            ds.runwayMonths = runwayMonths;
            ds.smbChurnRate = effectiveSmbChurn;
            ds.entChurnRate = effectiveEntChurn;
            ds.blendedCAC = blendedEffectiveCAC;
            ds.entCAC = entEffectiveCAC;

            var seriesBScore = 0;
            if (nrr >= 1.10) seriesBScore += 25;
            if (ltvCacRatio >= 3.0) seriesBScore += 25;
            if (blendedPayback <= 18) seriesBScore += 25;
            if (runwayMonths >= 6) seriesBScore += 25;
            ds.seriesBScore = seriesBScore;

            ds.mrrHistory.push(currentMRR);
            ds.nrrHistory.push(Math.round(nrr * 1000) / 10);
            ds.ltvCacHistory.push(Math.round(ltvCacRatio * 10) / 10);

            this._updateSeriesBCriteria(ds);

            var self = this;
            var nextPeriod = (state.currentPeriod || 1) + 1;
            if (this._cardTimer) clearTimeout(this._cardTimer);
            this._cardTimer = setTimeout(function() {
                self._updateEventCard({ currentPeriod: nextPeriod, domainState: ds });
            }, 600);

            return {
                period: state.currentPeriod,
                mrr: currentMRR,
                newMRR: Math.round(newMRR),
                expansionMRR: expansionMRR,
                churnedMRR: Math.round(churnedMRR),
                nrr: Math.round(nrr * 1000) / 10,
                ltvCacRatio: Math.round(ltvCacRatio * 10) / 10,
                cacPayback: Math.round(blendedPayback * 10) / 10,
                runway: runwayMonths,
                smbCustomers: ds.smbCustomers,
                entCustomers: ds.entCustomers,
                cash: ds.cash,
                seriesBScore: seriesBScore
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('mrrDisplay', 'domainState.totalMRR',
                (v) => '$' + Math.round(v).toLocaleString());
            uiManager.bind('nrrDisplay', 'domainState.nrr',
                (v) => Math.round(v * 1000) / 10 + '%');
            uiManager.bind('ltvCacDisplay', 'domainState.ltvCacRatio',
                (v) => (Math.round(v * 10) / 10) + 'x');
            uiManager.bind('runwayDisplay', 'domainState.runwayMonths',
                (v) => (v >= 60 ? '60+' : Math.round(v)) + ' mo');
            uiManager.bind('cacPaybackDisplay', 'domainState.cacPaybackMonths',
                (v) => Math.round(v) + ' mo');
            uiManager.bind('cashDisplay', 'domainState.cash',
                (v) => '$' + (Math.round(v / 1000)).toLocaleString() + 'K');
            uiManager.bind('smbCustomers', 'domainState.smbCustomers');
            uiManager.bind('entCustomers', 'domainState.entCustomers');
            uiManager.bind('smbChurn', 'domainState.smbChurnRate',
                (v) => (Math.round(v * 1000) / 10) + '%');
            uiManager.bind('entChurn', 'domainState.entChurnRate',
                (v) => (Math.round(v * 1000) / 10) + '%');
            uiManager.bind('smbLTV', 'domainState.totalMRR',
                () => {
                    var ds = window.mySimulation && window.mySimulation.state ? window.mySimulation.state.domainState : {};
                    if (!ds.smbChurnRate || ds.smbChurnRate === 0) return '$0';
                    var ltv = (ds.smbARPU || 166) * (ds.smbGrossMargin || 0.72) * (1 / ds.smbChurnRate);
                    return '$' + Math.round(ltv).toLocaleString();
                });
            uiManager.bind('entLTV', 'domainState.totalMRR',
                () => {
                    var ds = window.mySimulation && window.mySimulation.state ? window.mySimulation.state.domainState : {};
                    if (!ds.entChurnRate || ds.entChurnRate === 0) return '$0';
                    var ltv = (ds.entARPU || 3500) * (ds.entGrossMargin || 0.78) * (1 / ds.entChurnRate);
                    return '$' + Math.round(ltv).toLocaleString();
                });
            uiManager.bind('seriesBScore', 'domainState.seriesBScore');
        }

        _computeDisplayMetrics(state) {
            var ds = state.domainState;
            if (ds.totalMRR === 0) {
                ds.totalMRR = (ds.smbCustomers * ds.smbARPU) + (ds.entCustomers * ds.entARPU);
            }
            var smbLTV = ds.smbARPU * ds.smbGrossMargin * (1 / ds.smbChurnRate);
            var entLTV = ds.entARPU * ds.entGrossMargin * (1 / ds.entChurnRate);
            var blendedLTV = ((smbLTV * ds.smbCustomers) + (entLTV * ds.entCustomers)) / Math.max(1, ds.smbCustomers + ds.entCustomers);
            var blendedCACMix = ((ds.blendedCAC * ds.smbCustomers) + (ds.entCAC * ds.entCustomers)) / Math.max(1, ds.smbCustomers + ds.entCustomers);
            ds.ltvCacRatio = blendedCACMix > 0 ? blendedLTV / blendedCACMix : 0;
            ds.cacPaybackMonths = (ds.smbARPU * ds.smbGrossMargin) > 0 ? ds.blendedCAC / (ds.smbARPU * ds.smbGrossMargin) : 17.5;
        }

        _updateEventCard(state) {
            var period = (state.currentPeriod || 1);
            var idx = Math.min(period - 1, this.EVENT_CARDS.length - 1);
            var card = this.EVENT_CARDS[idx];
            if (!card) return;
            var lang = 'en';
            try {
                if (document.documentElement.lang && document.documentElement.lang.startsWith('es')) lang = 'es';
            } catch(e) {}
            var el = document.getElementById('eventCardText');
            if (el) el.innerHTML = card[lang] || card['en'];
        }

        _updateSeriesBCriteria(ds) {
            var nrrMet = ds.nrr >= 1.10;
            var ltvCacMet = ds.ltvCacRatio >= 3.0;
            var paybackMet = ds.cacPaybackMonths <= 18;
            var runwayMet = ds.runwayMonths >= 6;

            var criteria = [
                { id: 'nrrCriterion', met: nrrMet },
                { id: 'ltvCacCriterion', met: ltvCacMet },
                { id: 'cacPaybackCriterion', met: paybackMet },
                { id: 'runwayCriterion', met: runwayMet }
            ];

            criteria.forEach(function(c) {
                var el = document.getElementById(c.id);
                if (!el) return;
                var iconEl = el.querySelector('.helix-criterion-icon');
                if (c.met) {
                    el.classList.add('met');
                    if (iconEl) iconEl.textContent = '✅';
                } else {
                    el.classList.remove('met');
                    if (iconEl) iconEl.textContent = '⬜';
                }
            });
        }

        getChartConfig() {
            return {
                mrrChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: 'New MRR',
                                data: [],
                                backgroundColor: 'rgba(102, 187, 106, 0.85)',
                                borderRadius: 4
                            },
                            {
                                label: 'Expansion MRR',
                                data: [],
                                backgroundColor: 'rgba(100, 181, 246, 0.85)',
                                borderRadius: 4
                            },
                            {
                                label: 'Churned MRR',
                                data: [],
                                backgroundColor: 'rgba(229, 115, 115, 0.85)',
                                borderRadius: 4
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'MRR Waterfall by Quarter', color: '#90a4ae', font: { size: 12 } },
                            legend: { labels: { color: '#90a4ae', font: { size: 11 } } }
                        },
                        scales: {
                            x: { stacked: false, ticks: { color: '#90a4ae' }, grid: { color: 'rgba(255,255,255,0.05)' } },
                            y: { beginAtZero: true, ticks: { color: '#90a4ae', callback: function(v) { return '$' + (v/1000).toFixed(0) + 'K'; } }, grid: { color: 'rgba(255,255,255,0.05)' } }
                        }
                    }
                },
                unitEconChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: 'NRR (%)',
                                data: [],
                                borderColor: '#66bb6a',
                                backgroundColor: 'rgba(102,187,106,0.1)',
                                borderWidth: 2,
                                fill: false,
                                tension: 0.3,
                                yAxisID: 'yNRR'
                            },
                            {
                                label: 'LTV:CAC',
                                data: [],
                                borderColor: '#64b5f6',
                                backgroundColor: 'rgba(100,181,246,0.1)',
                                borderWidth: 2,
                                fill: false,
                                tension: 0.3,
                                yAxisID: 'yLTV'
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Unit Economics Trend', color: '#90a4ae', font: { size: 12 } },
                            legend: { labels: { color: '#90a4ae', font: { size: 11 } } }
                        },
                        scales: {
                            x: { ticks: { color: '#90a4ae' }, grid: { color: 'rgba(255,255,255,0.05)' } },
                            yNRR: { position: 'left', beginAtZero: false, ticks: { color: '#66bb6a', callback: function(v) { return v + '%'; } }, grid: { color: 'rgba(255,255,255,0.05)' } },
                            yLTV: { position: 'right', beginAtZero: true, ticks: { color: '#64b5f6', callback: function(v) { return v + 'x'; } }, grid: { drawOnChartArea: false } }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var ds = state.domainState;
            var labels = ds.mrrHistory.map(function(_, i) { return 'Q' + (i + 1); });
            return {
                mrrChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.mrrHistory.map(function(v, i) { return state.history && state.history[i] ? (state.history[i].results.newMRR || 0) : 0; }) },
                        { data: ds.mrrHistory.map(function(v, i) { return state.history && state.history[i] ? (state.history[i].results.expansionMRR || 0) : 0; }) },
                        { data: ds.mrrHistory.map(function(v, i) { return state.history && state.history[i] ? (state.history[i].results.churnedMRR || 0) : 0; }) }
                    ]
                },
                unitEconChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.nrrHistory },
                        { data: ds.ltvCacHistory }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history || !history.length) return {};
            var lastResult = history[history.length - 1].results || {};
            var finalNRR = lastResult.nrr || 0;
            var finalLtvCac = lastResult.ltvCacRatio || 0;
            var finalPayback = lastResult.cacPayback || 99;
            var finalRunway = lastResult.runway || 0;
            var finalMRR = lastResult.mrr || 0;
            var seriesBScore = lastResult.seriesBScore || 0;

            var qualified = finalNRR >= 110 && finalLtvCac >= 3.0 && finalPayback <= 18 && finalRunway >= 6;

            var insights = [];
            if (finalNRR >= 110) {
                insights.push('NRR above 110% — existing customers are driving organic growth.');
            } else {
                insights.push('NRR below 110% — focus on retention and upsell motions to unlock organic growth.');
            }
            if (finalLtvCac >= 3.0) {
                insights.push('LTV:CAC above 3x — strong unit economics justify continued growth investment.');
            } else {
                insights.push('LTV:CAC below 3x — improve ICP targeting or reduce CAC to meet investor thresholds.');
            }
            if (finalPayback <= 18) {
                insights.push('CAC payback within 18 months — healthy cash conversion cycle.');
            } else {
                insights.push('CAC payback exceeds 18 months — high burn risk for growth-stage company.');
            }

            return {
                qualified,
                finalNRR,
                finalLtvCac,
                finalPayback,
                finalRunway,
                finalMRR,
                seriesBScore,
                performance: qualified ? 'Series B Ready' : seriesBScore >= 50 ? 'Progressing' : 'Needs Work',
                insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            var ds = state.domainState;
            if (ds.runwayMonths < 4) return window.mySimulation.t('hint_low_runway');
            if (results.nrr < 95) return window.mySimulation.t('hint_low_nrr');
            if (results.ltvCacRatio < 1.5) return window.mySimulation.t('hint_low_ltv_cac');
            if (results.cacPayback > 24) return window.mySimulation.t('hint_high_payback');
            if (results.seriesBScore === 100) return window.mySimulation.t('hint_series_b_ready');
            return null;
        }

